sqlGroup.select:
select a.id, a.name AS name, a.job_type AS jobType, a.prod_line_or_dept AS prodLineOrDept, a.impact_level AS impactLevel, a.repair_status AS repairStatus, a.repair_accepted AS repairAccepted, rp.name AS repairerStaffName, dv.name AS deviceName, date_format( a.created_time, '%Y-%m-%d %H:%i:%s' ) as createdTime, cs.`name` AS createdStaffName, a.repairer_staff_id AS repairerStaffId, a.repair_accepted AS repairAccepted, DATE_FORMAT(a.repair_accepted_time, '%Y-%m-%d %H:%i:%s') AS repairAcceptedTime
from jml_device_repair a left join jml_staff cs ON a.created_staff_id = cs.id left join jml_staff rp ON a.repairer_staff_id = rp.id left join jml_device dv ON a.device_id = dv.id
and (a.repairer_staff_id = #{staff.staffId} or a.created_staff_id = #{staff.staffId})
and a.created_staff_id = #{staff.staffId}
and a.prod_line_or_dept = #{staff.prodLineOrDept}
and (a.name like '%${multiFiled}%')
and a.created_time >= str_to_date(#{startDate},'%Y-%m-%d')
and a.created_time <= date_add(str_to_date(#{endDate},'%Y-%m-%d'),interval 1 day)
and a.created_staff_id = #{createdStaffId}
and a.repairer_staff_id = #{repairerStaffId}
and a.prod_line_or_dept = #{prodLineOrDept}
group by a.id order by a.update_time desc
